# Public R wrappers generated by jamovi require every Level option as an
# explicit argument. Level options cannot have defaults in .a.yaml, so tests
# use this helper to pass NULL for unselected levels without changing the
# analysis definition used by jamovi.
run_survivalcont <- function(...) {
  args <- list(...)
  for (level_option in c("outcomeLevel", "dod", "dooc", "awd", "awod")) {
    if (!level_option %in% names(args))
      args[level_option] <- list(NULL)
  }
  do.call(ClinicoPath::survivalcont, args)
}

strip_survivalcont_html <- function(x) {
  trimws(gsub(
    "[[:space:]]+",
    " ",
    gsub("<[^>]*>", " ", paste(x, collapse = " "))
  ))
}

survivalcont_numeric_cell <- function(table, row, column) {
  as.numeric(table$getCell(rowNo = row, column)$value)
}

run_survivalcont_jamovi <- function(data, ..., .outputs = character()) {
  namespace <- environment(ClinicoPath::survivalcont)
  options_generator <- get("survivalcontOptions", envir = namespace)
  analysis_generator <- get("survivalcontClass", envir = namespace)
  args <- list(...)
  for (level_option in c("outcomeLevel", "dod", "dooc", "awd", "awod")) {
    if (!level_option %in% names(args))
      args[level_option] <- list(NULL)
  }
  options <- do.call(options_generator$new, args)
  for (output_name in .outputs) {
    output_option <- options$option(output_name)
    output_option$value <- list(value = TRUE, synced = FALSE)
  }
  analysis_generator$new(options = options, data = data)
}
